s;function p(i){return String(i).padStart(3,`0`)}async function x(i){try{return(await a(`../../../data/theory/i18n/${i}.json`)).default}catch{return(await import(`./chunk-C6vkP1hU.js`)).default}}async function T(i,t){let e=p(t);try{return(await g(`../../../data/theory/i18n/${i}/${e}.json`)).default}catch{return(await c$1(`../../../data/theory/i18n/en/${e}.json`)).default}}function q(i,t){return i.replace(/\{(\w+)\}/g,(e,o)=>o in t?String(t[o]):e)}var i={title:`Теорії`,intro:`Короткі пояснення того, як працює тренування: що означає кожна ідея, як її застосовувати і чого уникати. Кожна теорія має коротку й докладну версію.`,disclaimer:`Ці теорії є загальною освітою, а не медичною порадою. Якщо у вас біль, травма або захворювання, перед зміною тренувань порадьтеся з лікарем або фізіотерапевтом.`,searchLabel:`Пошук теорій`,searchPlaceholder:`Шукайте за назвою або ідеєю`,topicLabel:`Тема`,allTopics:`Усі теми`,count:`{shown} з {n} теорій`,empty:`Жодна теорія не відповідає вашому пошуку.`,reset:`Показати всі теорії`,short:`Коротко`,readMore:`Читати далі`,readLess:`Згорнути`,sources:`Джерела`,previous:`Назад`,next:`Далі`,backToList:`Усі теорії`,inTopic:`Ще в темі «{title}»`,notFound:`Цю теорію не знайдено.`};var o={foundations:`Основи тренування`,body:`Тіло і рух`,variables:`Змінні тренування`,patterns:`Рухові патерни`,programming:`Побудова програми`,equipment:`Обладнання`,space:`Простір і середовище`,conditioning:`Витривалість і кондиція`,mobility:`Розминка і рухливість`,recovery:`Відновлення`,safety:`Безпека та обмеження`,groups:`Окремі групи`,progress:`Відстеження прогресу`,myths:`Міфи`};var r$1={"1":{title:`Як тренування змінює тіло`,short:`Тренування є контрольованим викликом, який спонукає нервову систему, м’язи, серце та інші тканини ставати кращими в завданнях, які ви повторюєте. Прогрес приходить, коли цей виклик поєднується з достатнім відновленням, а навантаження зростає поступово, а не коли кожне тренування виснажує.`},"2":{title:`Складові фізичної форми`,short:`Фізична форма складається з кількох частково незалежних здібностей: сили, потужності, силової витривалості, аеробної витривалості, рухливості, рівноваги та координації. Знання про них допомагає обирати вправи під вашу ціль, адже різні тренування розвивають різне.`},"3":{title:`Цілі тренувань: загальна форма, сила, кондиція`,short:`Загальна фізична форма, сила та кондиція є різними пріоритетами, і кожен з них впливає на вибір вправ, зусилля, відпочинок і прогресію. Можна тренувати кілька якостей разом, але одна головна ціль полегшує складання програми та оцінку її результатів.`},"4":{title:`Рівні підготовки: початківець, середній, просунутий`,short:`Ваш рівень підготовки описує досвід і навички у вправах та навантаженнях, які ви справді виконуєте, а не те, наскільки спортивно ви виглядаєте. Початківці зазвичай прогресують завдяки простій практиці та помірному обсягу, тоді як досвідченим часто потрібне більш ретельне планування.`},"5":{title:`Перевірка готовності: коли спершу звернутися до фахівця`,short:`Перевірка готовності виявляє проблеми зі здоров’ям або симптоми, через які може знадобитися порада фахівця до того, як ви почнете тренуватися інтенсивніше. Вона допомагає ухвалювати безпечніші рішення, але не є медичним діагнозом і не забороняє вам рухатися автоматично.`},"6":{title:`Рекомендації щодо фізичної активності`,short:`Рекомендації щодо фізичної активності визначають мінімум щотижневої активності, пов’язаний із важливою користю для здоров’я. Для більшості дорослих корисна ціль: регулярна аеробна активність помірної або високої інтенсивності плюс силові тренування основних груп м’язів щонайменше два дні на тиждень.`},"7":{title:`Постановка реалістичних цілей у тренуванні`,short:`Корисна ціль у тренуванні є конкретною, вимірюваною, реалістичною і прив’язаною до строків. Поєднайте бажаний результат із тижневими діями, які ви контролюєте, щоб бачити прогрес, навіть коли результати приходять повільно.`},"8":{title:`Регулярність і звички тренувань`,short:`Регулярність означає тренуватися достатньо часто і достатньо довго, щоб покращення накопичувалися, зокрема й у неідеальні тижні. Короткі тренування, які можна повторювати, та передбачуваний розпорядок зазвичай працюють краще за амбітний план, який ви кидаєте після кількох занять.`},"9":{title:`Основні групи м’язів`,short:`Основні групи м’язів працюють разом, щоб рухати й стабілізувати тіло, тому їх тренування потребує більшого, ніж ізолювання окремих м’язів. Розуміння того, що робить кожна група, допомагає складати збалансовані заняття і бачити, чому один рух може навантажувати кілька зон одночасно.`},"10":{title:`Як працюють м’язи: концентрична, ексцентрична та ізометрична робота`,short:`М’язи створюють силу або протидіють їй, коли вкорочуються, подовжуються чи утримують положення. Ці концентричні, ексцентричні та ізометричні дії часто відбуваються в одній вправі, і вони допомагають зрозуміти, що означає контролювати вагу.`},"11":{title:`Типи м’язових волокон`,short:`Скелетні м’язи містять волокна, які відрізняються стійкістю до втоми та силою, яку вони створюють, і їх зазвичай описують як тип I і тип II. Обидва типи допомагають вам рухатися, а тренування покращує їхню роботу, не перетворюючи вас на повністю інший «тип волокон».`},"12":{title:`Суглоби та амплітуда руху`,short:`Суглоби рухаються в межах амплітуд, які залежать від анатомії, м’язового контролю, гнучкості та комфорту. Тренування в корисній амплітуді, яку ви контролюєте, зазвичай розвиває здатності, що краще переносяться в життя, ніж примусове приведення всіх до однакових положень.`},"13":{title:`Хребет, кор і брейсинг`,short:`Хребет підтримує вас і дає змогу рухатися, а м’язи тулуба навколо нього допомагають контролювати сили під час вправ. Брейсинг (bracing): це узгоджене напруження тулуба, яке може покращити стабільність, і воно відрізняється від утримання однієї жорсткої пози в усіх видах активності.`},"14":{title:`Енергетичні системи під час вправ`,short:`Вправи використовують три енергетичні системи, що перекриваються: фосфагенну, гліколітичну та окисну. Усі три працюють постійно, але значення кожної змінюється залежно від того, наскільки інтенсивно і довго ви рухаєтеся та скільки відпочиваєте між зусиллями.`},"15":{title:`Пульс і тренувальні зони`,short:`Пульс може допомогти оцінити, наскільки важкою є аеробна вправа, але тренувальні зони є наближеннями, а не універсальними біологічними межами. Поєднуйте пульс із диханням, тестом розмови, відчуттям зусилля та власними чинниками здоров’я, щоб обрати інтенсивність, яку можна втримати.`},"16":{title:`Дихання під час вправ`,short:`Дихання підтримує рух, допомагає керувати тиском у тулубі й змінюється разом із тим, наскільки інтенсивно ви працюєте. Для більшості початківців практичний спосіб не затримувати подих без потреби: рівний ритм і видих на складнішій частині кожного повторення.`},"17":{title:`Моторне навчання: як формується техніка`,short:`Техніка вправи є навичкою, яку ви будуєте повторною, уважною практикою та корисним зворотним зв’язком. Вправи опановуються ефективніше, якщо починати з легших версій, зберігати стабільність повторень і ускладнювати лише тоді, коли ви маєте контроль.`},"18":{title:`Ріст м’язів (гіпертрофія)`,short:`Гіпертрофія м’язів: це збільшення їхнього розміру внаслідок повторюваних тренувань і відновлення. Механічне навантаження є головним стимулом, а обсяг тренувань, зусилля, достатнє харчування та сон впливають на те, наскільки ви можете адаптуватися.`},"19":{title:`Підходи, повторення та відпочинок`,short:`Повторення: це один рух вправи, підхід: це група повторень, а відпочинок розділяє підходи чи вправи. Разом вони визначають, скільки роботи вміщується в заняття і наскільки добре ви зберігаєте силу, техніку чи витривалість.`},"20":{title:`Діапазони повторень і що вони розвивають`,short:`Діапазони повторень підказують, на чому робити акцент, але не ділять тренування на жорсткі категорії. Важча робота з малою кількістю повторень найважливіша для максимальної сили, м’язи можуть рости в багатьох діапазонах, а багато повторень можуть розвивати локальну м’язову витривалість.`},"21":{title:`Обсяг тренувань`,short:`Обсяг тренувань: це скільки роботи ви виконуєте. У силових тренуваннях його зазвичай рахують як кількість складних підходів на групу м’язів за тиждень. Достатній обсяг рухає прогрес уперед, але підходи понад те, від чого ви можете відновитися, можуть знизити якість тренування.`},"22":{title:`Інтенсивність: навантаження і відсоток від 1RM`,short:`Інтенсивність у силових тренуваннях часто означає, наскільки важким є навантаження порівняно з вашим максимумом на одне повторення, тобто 1RM. Досвідчені атлети можуть задавати навантаження у відсотках. Початківцям безпечніше добирати вагу за контрольованими повтореннями та зусиллям, без максимального тесту.`},"23":{title:`Оцінка суб’єктивного зусилля (RPE)`,short:`Оцінка суб’єктивного зусилля (RPE): це ваша власна оцінка того, наскільки важкою здається вправа. Якщо записувати її поруч із виконаним, можна помічати заняття, які були легшими чи важчими, ніж очікувалося, і потроху коригувати майбутні тренування.`},"24":{title:`Повторення в запасі (RIR)`,short:`Повторення в запасі (RIR): це ваша оцінка того, скільки ще чистих повторень ви могли б виконати до кінця підходу. Вона допомагає добирати навантаження, які важкі, але залишають пару повторень у запасі, без перевірки максимуму чи роботи до відмови в кожному підході.`},"25":{title:`Темп виконання вправ`,short:`Темп виконання: це швидкість і тривалість кожної фази повторення. Контрольований темп допомагає відпрацьовувати техніку і робить тренування легшими для повторення. Дуже повільні повторення не обов’язково кращі для сили чи росту м’язів.`},"26":{title:`Підходи на час і утримання`,short:`Підходи на час і статичні утримання вимірюють зусилля в секундах, а не в повтореннях. Вони підходять для планки, стільця біля стіни, висів і кондиційних інтервалів, поки ваше положення чи темп лишаються незмінними весь час.`},"27":{title:`Частота тренувань`,short:`Частота тренувань: це те, як часто ви займаєтеся за тиждень: загалом або для однієї групи м’язів. Добрий розклад дає достатньо практики й роботи для прогресу та водночас залишає час на відновлення й решту життя.`},"28":{title:`Порядок вправ у занятті`,short:`Порядок вправ визначає, які вправи ви виконуєте найсвіжішим. Ставте пріоритетні вправи, технічно складні рухи та вправи з великою силою на початок, а простіші допоміжні, кор чи кондиційні вправи розміщуйте там, де вони служать меті заняття.`},"29":{title:`Тренування до відмови`,short:`Тренування до відмови означає продовжувати підхід, доки ви не зможете виконати ще одне повторення за обраним стандартом. Воно потребує багато зусиль, але для сили чи росту м’язів воно не обов’язкове, та додає втому і ризики для техніки.`},"30":{title:`Планування тривалості заняття`,short:`Планування тривалості заняття означає оцінити, скільки справді тривають розминка, підходи, відпочинок, зміна вправ та кондиційна робота, якщо вона є. Реалістичне тренування на 20–45 хвилин, що охоплює ваші головні пріоритети, часто дає більше, ніж довший план, який ніколи не вміщується у ваш день.`},"31":{title:`Базові рухові патерни`,short:`Рухові патерни групують вправи за тим, що робить тіло, а не за окремими м’язами. Присід, нахил із відведенням тазу, випад, жим, тяга, перенесення, стабілізація кору та пересування дають практичний спосіб обрати збалансований набір вправ.`},"32":{title:`Патерн присіду`,short:`Присід опускає і піднімає тіло через одночасне згинання та розгинання стегон, колін і щиколоток. Навчившись присіду, який зручний для вашого тіла, ви допоможете собі в піднятті вантажів, у сидінні та багатьох силових вправах для ніг.`},"33":{title:`Патерн нахилу з відведенням тазу`,short:`Нахил із відведенням тазу (hip hinge) згинається переважно в тазостегнових суглобах, тоді як тулуб лишається під контролем. Він є основою станової тяги, румунської станової тяги та рухів із гирею і тренує сідничні м’язи та задню поверхню стегна створювати силу.`},"34":{title:`Випади й тренування однієї ноги`,short:`Випади, спліт-присіди та сходження на підвищення дають більше навантаження на одну ногу, ніж на іншу, і випробовують рівновагу та контроль стегон. Вони можуть розвивати практичну силу ніг і показувати різницю між лівим і правим боком.`},"35":{title:`Горизонтальні жими`,short:`Горизонтальний жим виносить руки вперед від тулуба, як у віджиманнях, жимах на груди та жимі лежачи. Він переважно тренує груди, трицепси та передню частину плечей і вимагає контролю тулуба та плечей.`},"36":{title:`Вертикальні жими`,short:`Вертикальний жим штовхає опір над головою, як у жимі гантелей над головою, жимі штанги стоячи чи віджиманнях із піднятим тазом (pike push-up). Він тренує силу плечей і рук та вимагає спільної роботи лопаток, тулуба й стегон.`},"37":{title:`Горизонтальні тяги`,short:`Горизонтальна тяга підтягує кисті або лікті до тулуба, як у тягах до пояса. Такі тяги тренують верх спини, найширші м’язи, задні дельти та згиначі ліктя і врівноважують багато жимових вправ.`},"38":{title:`Вертикальні тяги`,short:`Вертикальна тяга опускає лікті вниз із положення над головою, як у підтягуваннях, підтягуваннях зворотним хватом і тязі верхнього блока. Вона переважно працює на найширші м’язи та верх спини, а руки й тулуб суттєво допомагають.`},"39":{title:`Тренування кору: проти розгинання, проти обертання, проти бічного згинання`,short:`Сила кору включає опір небажаному руху, а не лише згинання тулуба. Вправи проти розгинання, проти обертання та проти бічного згинання тренують тулуб лишатися під контролем, коли на нього діють сили.`},"40":{title:`Перенесення вантажу`,short:`Перенесення вантажу означає ходьбу з вагою в руках, як-от із гантелями чи гирями. Перенесення просте, але важке: воно одночасно тренує силу хвату, стабільність тулуба, поставу та ходу.`},"41":{title:`Ізолюючі вправи`,short:`Ізолюючі вправи зосереджені на русі в одному головному суглобі, як-от згинання рук на біцепс чи розгинання ніг. Вони дають м’язу додаткову практику або тренувальний обсяг понад те, що вже дають багатосуглобові рухи.`},"42":{title:`Баланс жимів і тяг`,short:`Жими та тяги тренують різні, але такі, що перекриваються, частини верху тіла. Виконання обох розвиває всебічну силу і не дає програмі заповнитися самими жимами.`},"43":{title:`Принципи тренування`,short:`Хороше тренування дотримується кількох взаємопов’язаних принципів: специфічності, прогресивного перевантаження, індивідуалізації, відновлення, регулярності та оборотності. Вони є надійнішим орієнтиром, ніж копіювання режиму просунутого атлета.`},"44":{title:`Прогресивне перевантаження`,short:`Прогресивне перевантаження означає повільно ускладнювати вправу, поки тіло адаптується. Воно потрібне, щоб і далі покращуватися, і його можна застосовувати через повторення, опір, контроль руху, амплітуду або складнішу вправу, а не лише через важчу вагу.`},"45":{title:`Подвійна прогресія`,short:`Подвійна прогресія: простий спосіб рухатися вперед у силових тренуваннях: ви додаєте повторення в межах обраного діапазону, а потім додаєте вагу. Це майже прибирає здогадки під час вибору нового навантаження.`},"46":{title:`Програми на все тіло, верх/низ і спліти`,short:`Тренувальний спліт: це спосіб розподілити вправи протягом тижня. Тренування на все тіло, верх/низ і спліти за групами м’язів можуть розвивати силу й м’язи, якщо загальна робота, зусилля та відновлення вам підходять.`},"47":{title:`Побудова тренувального тижня`,short:`Тренувальний тиждень розташовує важкі заняття, легшу активність і відновлення так, щоб план пасував до вашого реального життя. Добрий розклад дає тренуватися досить часто і не накопичує втому від важких тренувань підряд.`},"48":{title:`Основи періодизації`,short:`Періодизація означає планування того, як тренувальний стрес змінюється з часом. Лінійний, хвилеподібний та блоковий підходи: це способи організувати прогрес, але початківці часто можуть покращуватися з набагато простішою програмою, якої вони дотримуються.`},"49":{title:`Тижні розвантаження (дилоад)`,short:`Дилоад: це короткий період легших тренувань, під час якого втома спадає, а ви й далі практикуєте рухи. Дилоади можна планувати заздалегідь або вдаватися до них, коли звичне навантаження перестає бути таким, від якого ви встигаєте відновлюватися.`},"50":{title:`Вибір вправ`,short:`Обирайте вправи, що відповідають вашій цілі, рівню підготовки, обладнанню, простору та будь-яким обмеженням. Найкраща вправа: та, яку ви можете виконувати безпечно, регулярно повторювати та поступово ускладнювати.`},"51":{title:`Прогресії та регресії`,short:`Прогресія ускладнює вправу, а регресія її полегшує. Обидві є звичайними тренерськими інструментами, щоб підібрати вправу до вашої сили, техніки та відновлення.`},"52":{title:`Суперсети та кругові тренування`,short:`Суперсет поєднує вправи з малим відпочинком між ними, а кругове тренування проходить кілька рухів по колу. Обидва можуть заощадити час, але втома та коротше відновлення можуть знизити якість важких або дуже технічних вправ.`},"53":{title:`Плато в тренуванні`,short:`Плато в тренуванні: це період, коли здібність перестає покращуватися, хоча ви продовжуєте практику. Плато трапляються часто, і причиною може бути відновлення, замало виклику, нестабільні вимірювання або повільніший прогрес, що приходить із досвідом.`},"54":{title:`Детренування і повернення після перерви`,short:`Детренування: це часткова втрата форми після скорочення або припинення тренувань. Обережне повернення відновлює ваші можливості крок за кроком, не очікуючи, що тіло одразу впорається зі старим навантаженням.`},"55":{title:`Тренування з вагою тіла`,short:`Тренування з вагою тіла використовує ваше тіло як опір для сили й практики руху. Присіди, віджимання, випади, планки та підтягування можуть привести вас дуже далеко без купівлі повного набору ваг.`},"56":{title:`Тренування з гантелями`,short:`Гантелі: універсальні вільні ваги для жимів, тяг, присідів, нахилів і вправ на одну ногу. Кожна рука рухається самостійно, а хват можна змінювати, але потрібно звертати увагу на рівновагу, поводження з гантелями та їх зберігання.`},"57":{title:`Тренування з гирею`,short:`Гиря: це вага з ручкою, у якої маса зміщена відносно хвату. Її можна використовувати для контрольованих силових вправ і для швидших рухів, як-от махи, але технічніші вправи потребують цілеспрямованої практики.`},"58":{title:`Тренування з еспандерами`,short:`Еспандери дають портативний опір, який зазвичай зростає, коли стрічка розтягується. Їх можна використовувати для жимів, тяг і допоміжної роботи, якщо безпечно закріплювати та підтримувати їх у хорошому стані.`},"59":{title:`Тренування зі штангою`,short:`Штанга дає змогу з часом трохи збільшувати навантаження у вправах на кшталт присідів, станової тяги, жимів і тяг. Вона добре підходить для розвитку високого рівня сили, але потребує грамотної техніки, правильного налаштування обладнання та заходів безпеки.`},"60":{title:`Тренажери та блокові рами`,short:`Силові тренажери та блокові станції дають регульований опір і можуть спростити підготовку до вправи. Вони є ефективними інструментами силових тренувань поряд із вільними вагами, а не гіршою заміною.`},"61":{title:`Перекладина: встановлення і безпека`,short:`Перекладина дає змогу виконувати підтягування та висіти, але лише якщо вона надійно встановлена та розрахована на те, як ви її використовуєте. Якість кріплення важить більше, ніж кількість повторень, які ви можете зробити.`},"62":{title:`Лави, степи та скакалки`,short:`Лави, степи та скакалки додають багато вправ удома й у залі. Кожен із них добре працює лише тоді, коли розмір, стійкість і вільний простір відповідають руху та людині, яка ним користується.`},"63":{title:`Вибір правильного навантаження`,short:`Правильне навантаження досить важке, щоб змусити вас працювати, і досить легке, щоб кожне повторення лишалося контрольованим. Як початківець ви можете обирати вагу за якістю руху та кількістю повторень у запасі, не перевіряючи максимальний підйом.`},"64":{title:`Тренування з побутовими замінниками`,short:`Побутові предмети іноді можуть замінити тренувальне обладнання як легкий опір або опора. Користуйтеся ними лише після того, як перевірите їхню стійкість, яке навантаження вони витримують, їхній хват і те, що ви плануєте з ними робити.`},"65":{title:`Корисний простір і вільна зона для вправ`,short:`Корисний простір для тренувань охоплює не лише місце, де ви стоїте, а й усе, куди рухаються ваше тіло та обладнання під час кожного повторення. Його вимірювання допомагає уникати зіткнень і дає TrainUp змогу підбирати вправи, які справді вміщуються.`},"66":{title:`Висота стелі та вправи над головою`,short:`Висота стелі визначає, чи практичні жими над головою, підтягування, стрибки та стрибки зі скакалкою. Рух може вміститися, поки ви стоїте нерухомо, і стати небезпечним, коли руки, вантаж чи тіло піднімаються вгору.`},"67":{title:`Покриття для тренувань і взуття`,short:`Підлога та взуття впливають на стабільність, зчеплення та те, наскільки важким здається кожне приземлення. Найкраще поєднання залежить від того, чи рух переважно про підйом ваги, біг, стрибки чи повільну роботу на рухливість.`},"68":{title:`Шум і удари під час тренувань удома`,short:`Домашні тренування можуть турбувати сусідів і бити по підлозі, здебільшого через стрибки та впущені ваги. Вправи з меншим ударним навантаженням усе одно дають справжню кондицію з набагато меншим шумом.`},"69":{title:`Тренування в залі: етикет і безпека`,short:`Безпечне тренування в залі означає хорошу техніку та турботу про спільне обладнання й людей навколо. Чіткий етикет знижує ризик травм і полегшує користування обладнанням усім, коли в залі людно.`},"70":{title:`Тренування просто неба: погода і рельєф`,short:`На вулиці погода, ґрунт, світло та обладнання змінюються щодня. Коригування того, наскільки сильно і де ви працюєте, робить прогулянки, біг і тренування в парку безпечнішими та легшими для підтримки.`},"71":{title:`Побудова аеробної бази`,short:`Аеробна база: це ваша здатність довго підтримувати досить комфортну активність. Її розвиток полегшує повсякденний рух і важчі кондиційні заняття.`},"72":{title:`Кардіо з постійним темпом`,short:`Кардіо з постійним темпом утримує зусилля досить рівним протягом усього заняття, наприклад під час ходьби, легкого бігу, велосипеда чи на кардіотренажерах. Воно розвиває витривалість без повторюваних інтервалів на максимум.`},"73":{title:`Інтервальне тренування`,short:`Інтервальне тренування чергує важчу роботу з легшим відновленням. Задаючи тривалість і складність кожної частини, ви можете покращувати кондицію крок за кроком, і жодне заняття не мусить бути тестом на максимум.`},"74":{title:`HIIT і табата`,short:`Високоінтенсивне інтервальне тренування (HIIT) чергує справді важкі зусилля з відновленням, а табата: це один конкретний формат: 20 секунд роботи та 10 секунд відпочинку. Жоден із термінів не означає просто будь-яке швидке тренування.`},"75":{title:`Співвідношення роботи та відпочинку`,short:`Співвідношення роботи та відпочинку порівнює, як довго ви працюєте і як довго відновлюєтеся. Співвідношення на кшталт 1:3, 1:1 та 2:1 визначають, наскільки щільним відчувається тренування, а їхній ефект залежить і від того, наскільки важкий інтервал роботи.`},"76":{title:`Кондиційні вправи з низьким ударним навантаженням`,short:`Кондиційні вправи з низьким ударним навантаженням підвищують дихання та пульс із меншою кількістю жорстких приземлень. Вони підходять початківцям, людям, яким потрібно обмежити удари, і всім, хто тренується там, де шум є проблемою.`},"77":{title:`Пліометрика і стрибки`,short:`Пліометрика тренує вибуховий рух через швидке розтягнення та вкорочення м’язів, зазвичай за допомогою підстрибувань, скачків і стрибків. Вона потребує контрольованих приземлень, поступового нарощування та достатнього відпочинку, щоб кожне повторення лишалося чітким.`},"78":{title:`Основи техніки бігу`,short:`Техніка бігу стосується постави, часу кроку та поступового звикання до повторюваних ударів. Як початківець ви виграєте більше від комфортного, повторюваного бігу та поступового нарощування, ніж від копіювання одного «ідеального» постановлення стопи.`},"79":{title:`Навички стрибків зі скакалкою`,short:`Скакалка: це портативна кондиційна вправа, що потребує відчуття часу обертання та малих повторюваних підскоків. Правильно підберіть довжину скакалки, контроль зап’ястя та ритм приземлення, перш ніж пробувати довгі чи швидкі інтервали.`},"80":{title:`Поєднання сили та кардіо`,short:`Виконання і силових тренувань, і кардіо розвиває м’язову та серцево-судинну форму. Для більшості любителів розумний тижневий розклад дає покращуватися в обох напрямках, тож обирати щось одне не потрібно.`},"81":{title:`Розминка`,short:`Розминка готує ваше дихання, кровообіг, суглоби, м’язи та координацію до майбутньої роботи. Коротка загальна розминка з наступним відпрацюванням вправи, яку ви збираєтеся виконувати, зазвичай допомагає більше, ніж фіксований набір розтяжок.`},"82":{title:`Заминка`,short:`Заминка плавно переводить тіло від важкої активності до спокою легким рухом і спокійним диханням. Вона може бути приємною і її легко вмістити, але немає добрих доказів, що вона запобігає відстроченому болю в м’язах.`},"83":{title:`Рухливість і гнучкість`,short:`Гнучкість: це амплітуда, у якій може рухатися суглоб, а рухливість: ваша здатність самостійно контролювати цю амплітуду. Під час вибору вправ амплітуда, яку ви можете використовувати під контролем, важить більше, ніж найглибша позиція, якої ви можете досягти.`},"84":{title:`Статичне та динамічне розтягування`,short:`Статичне розтягування утримує положення, а динамічне проходить амплітуду під контролем. Обидва можуть допомогти підготуватися до руху чи покращити гнучкість, якщо добирати їх під свою ціль і тримати інтенсивність комфортною.`},"85":{title:`Рухливість стегон`,short:`Рухливість стегон: це комфортний рух у тазостегнових суглобах: згинання, розгинання, обертання та відведення ноги вбік. Вона допомагає досягати корисних положень у присіді, нахилі та випаді, хоча анатомія стегон і комфортні амплітуди в різних людей різні.`},"86":{title:`Рухливість грудного відділу хребта та плечей`,short:`Грудний відділ хребта та плечі беруть участь у тягнутті вгору, обертанні, жимах над головою та багатьох тягових рухах. Робота над рухливістю може полегшити ці рухи, якщо ви також розвиваєте силу та контроль, щоб ними користуватися.`},"87":{title:`Відновлення між заняттями`,short:`Між заняттями втома спадає, а тіло адаптується до тренувань. Добрий план поєднує важкі тренування з достатнім відпочинком або легшою активністю, щоб ви могли працювати тиждень за тижнем.`},"88":{title:`Сон і тренування`,short:`Сон підтримує фізичне відновлення, навчання, настрій та стабільну результативність у тренуваннях. Дорослим загалом потрібно щонайменше сім годин на добу, а багатьом найкраще підходить приблизно сім–дев’ять годин якісного сну.`},"89":{title:`Відстрочений біль у м’язах`,short:`Відстрочений біль у м’язах (DOMS): це тимчасова болючість і скутість, що часто настає після нового або незвично важкого тренування. Вона наростає після вправ і найсильніша зазвичай приблизно через 24–72 години.`},"90":{title:`Перенапруження і перетренованість`,short:`Перенапруження (overreaching): це тимчасове падіння результативності після накопичення більшого тренувального стресу, ніж тіло може зараз відновити. Справжній синдром перетренованості серйозніший і триваліший, і одне невдале тренування не говорить, що він у вас є.`},"91":{title:`Гідратація`,short:`Достатня гідратація підтримує кровообіг, регуляцію температури та результативність у вправах. Скільки потрібно пити, залежить від того, скільки ви потієте, від погоди та тривалості тренування, а надмірне споживання води також може бути небезпечним.`},"92":{title:`Основи харчування для активних людей`,short:`Тренування проходять краще, коли ви їсте достатньо їжі, різноманітні поживні речовини та достатньо білка для відновлення й адаптації. TrainUp пояснює загальні принципи харчування і не дає раціонів, цілей щодо калорій чи лікувальних дієт.`},"93":{title:`Щоденна готовність і стрес`,short:`Готовність: це те, наскільки ви підготовлені та наскільки добре працюєте на початку заняття. Поганий сон, хвороба та життєвий стрес можуть змінити, скільки тренування вам підходить цього дня, навіть якщо записаний план лишається тим самим.`},"94":{title:`Активне відновлення`,short:`Активне відновлення: це легкий рух між важчими тренуваннями. Ходьба, легка їзда на велосипеді та м’яка рухливість тримають вас у русі, не додаючи другого важкого тренування.`},"95":{title:`Техніка перед навантаженням`,short:`Хороша техніка робить рух повторюваним і контрольованим до того, як ви додаєте опір. Збільшуйте навантаження лише тоді, коли можете зберегти положення, амплітуду руху та впевненість.`},"96":{title:`Біль чи дискомфорт: як відрізнити`,short:`Вправи часто приносять м’язове зусилля, втому та короткочасну болючість, але біль, що є гострим, посилюється або супроводжується нервовими симптомами, потребує уваги. Проста перевірка симптомів допомагає обрати безпечніший наступний крок, не намагаючись щось діагностувати.`},"97":{title:`Тривожні ознаки: коли негайно зупинитися`,short:`Деякі симптоми під час вправ можуть сигналізувати про термінову медичну проблему, а не про звичайну втому. Їх помітити важливіше, ніж завершити тренування чи досягти запланованої цілі.`},"98":{title:`Осьове навантаження на хребет`,short:`Осьове навантаження на хребет: це стискальна сила, що проходить уздовж хребта під час руху чи силового тренування. Знання про нього пояснює, чому деякі вправи можуть вам не підходити, якщо ви хочете варіантів із меншим навантаженням на хребет.`},"99":{title:`Тренування з чутливими колінами`,short:`Чутливі коліна можуть робити деякі рухи, глибини чи рівні ударного навантаження некомфортними. Розумний вибір у тренуванні може зменшити кількість загострень, яких можна уникнути, але симптоми в колінах, що тривають або сильні, потребують професійної оцінки.`},"100":{title:`Тренування з чутливою поперековою ділянкою`,short:`Чутлива поперекова ділянка може впливати на те, які навантаження, амплітуди та положення ви переносите під час вправ. Планування загальної фізичної форми може віддавати перевагу комфортним варіаціям і поступовій прогресії, але воно не замінює клінічної оцінки чи реабілітації.`},"101":{title:`Тренування з чутливими плечима`,short:`Те, як почувається плече, може залежати від кута жиму, хвату, амплітуди руху та навантаження. Вибір варіацій, які ви переносите, допомагає залишатися активним, але біль у плечі без очевидної причини або біль, що не минає, потребує професійної оцінки.`},"102":{title:`Тренування з чутливими зап’ястями`,short:`Зап’ястя можуть боліти, коли кисті несуть вагу вашого тіла або тримають вантаж під незручним кутом. Зміна хвату, опори чи вправи іноді може зменшити навантаження, поки ви продовжуєте тренувати той самий руховий патерн.`},"103":{title:`Складність координації та безпечний вибір вправ`,short:`Складність координації: це те, скільки рівноваги, відчуття часу та контролю руху вимагає вправа. Підбір її до вашого досвіду та рівня втоми дає змогу відпрацьовувати хорошу техніку, перш ніж додавати швидкість чи навантаження.`},"104":{title:`Страхування і безпечний скид ваги`,short:`Страхування означає, що хтось допомагає, коли ви не можете безпечно завершити повторення. Незалежно від того, чи тренуєтеся ви з партнером, чи самі, правильно налаштуйте стійку, оберіть вагу, яку контролюєте, і знайте, що робитимете, якщо підйом не вдасться.`},"105":{title:`Старт із нуля`,short:`Як початківець ви можете стати міцнішим завдяки невеликому розпорядку, який можна повторювати. У перший місяць зосередьтеся на освоєнні рухів, комфортному зусиллі та регулярній появі на тренуванні, а підняття максимально можливої ваги залиште на потім.`},"106":{title:`Тренування після 50`,short:`Після 50 ви все ще можете розвивати силу та форму, а регулярні вправи допомагають зберігати рухливість і самостійність. Будуйте план на основі вашого здоров’я, тренувального досвіду, рівноваги та відновлення. Вік понад 50 не означає, що вам потрібен той самий легкий розпорядок, що й усім однолітками.`},"107":{title:`Силові тренування для підлітків`,short:`Силові тренування під наглядом, розроблені для вашого віку, можуть допомогти розвинути координацію, силу та впевненість у рухах. Спершу йдуть хороша техніка та поступовий прогрес, а копіювання програми дорослого на максимальні ваги є хибною моделлю.`},"108":{title:`Вправи під час вагітності та після пологів`,short:`Фізична активність часто корисна під час неускладненої вагітності та після пологів, але те, що потрібно вашому тілу, у ці періоди може сильно змінюватися. Отримайте індивідуальну пораду від вашої команди з акушерського супроводу, особливо якщо у вас є симптоми чи медичні ускладнення.`},"109":{title:`Початок занять із надлишковою вагою тіла`,short:`Люди будь-якої статури можуть ставати сильнішими, тренованішими та здоровішими завдяки відповідному виду активності. Хороший початок зосереджується на комфорті, меншому ударному навантаженні та здатності робити більше, а вага тіла: лише один із кількох способів виміряти успіх.`},"110":{title:`Короткі тренування для зайнятого графіка`,short:`Добре сплановане тренування на 10–20 хвилин може сформувати звичку тренуватися та покращити форму. Якщо ви зайняті, короткі заняття, які ви виконуєте часто, зазвичай працюють краще за амбітний план, якого ви не можете дотримуватися.`},"111":{title:`Ведення журналу тренувань`,short:`Журнал тренувань фіксує, що ви планували, що зробили і як це відчувалося. Регулярне його ведення допомагає відрізнити справжній прогрес від звичайних щоденних коливань і дає кращу інформацію, коли ви змінюєте програму.`},"112":{title:`Вимірювання силового прогресу`,short:`Силовий прогрес може проявлятися в більшій кількості повторень, важчих навантаженнях чи складніших варіаціях вправи. Чесне порівняння зберігає однакову техніку та умови, а особистий рекорд: лише один із показників, що мають значення.`},"113":{title:`Вимірювання прогресу в кондиції`,short:`Ваша кондиція покращується, коли ви можете продовжувати довше, долати відстань швидше або виконувати те саме завдання з меншим зусиллям. Повторення простих тестів у подібних умовах полегшує читання тенденцій витривалості.`},"114":{title:`Тенденції ваги тіла та вимірювання`,short:`Вага тіла та обхвати змінюються з причин, окрім набору чи втрати жиру, як-от рідина й травлення. Якщо ви вирішите їх відстежувати, тенденції з часом говорять більше, ніж окремі показники.`},"115":{title:`Прості тести фізичної форми`,short:`Прості польові тести дають швидкий знімок вашої силової витривалості, рівноваги чи кондиції. Вони найкорисніші, коли ви повторюєте той самий тест однаково, а порівняння себе з одним показником, призначеним для всіх, говорить набагато менше.`},"116":{title:`Коригування плану за зворотним зв’язком`,short:`Ваш план працює найкраще, коли виконана робота та те, як вона відчувалася, формують те, що буде далі. Невеликі обережні зміни покращують відповідність. Змінюйте одну річ за раз і не чіпайте тренування, поки ви його виконуєте.`},"117":{title:`Міф: можна спалити жир з однієї частини тіла`,short:`Тренування преса не дає надійно обирати, де тіло втрачає жир. Цілеспрямовані вправи зміцнюють м’язи, які ви тренуєте, а те, де лежить жир і як він змінюється, залежить від ширших біологічних і поведінкових чинників.`},"118":{title:`Міф: силові тренування роблять жінок громіздкими`,short:`Силові тренування не роблять жінок автоматично дуже мускулистими. Звичайні результати: більша сила та краща функція м’язів, а те, скільки видимих м’язів ви наростите, залежить від тренувань, часу, харчування та вашої біології.`},"119":{title:`Міф: кардіо руйнує набір м’язів`,short:`Аеробні вправи та силові тренування можуть працювати разом в одній програмі. Деякі поєднання можуть трохи зменшувати певний приріст сили чи потужності, але кардіо не скасовує ріст м’язів автоматично.`},"120":{title:`Міф: без болю немає результату`,short:`Зусилля та поступово важчі тренування розвивають форму, але для покращення біль чи сильна болючість не потрібні. Прагніть до виклику, який можете контролювати, до хорошої техніки та відновлення, і не міряйте успіх тим, скільки ви страждаєте.`}};var s={ui:i,topics:o,theories:r$1};var r=s;var c=[{path:``,pathMatch:`full`,redirectTo:`/theories`},...w.map(e=>({path:e.slug,data:{theory:e.slug,meta:m$1(l({},z(s$2,`/theory/${e.slug}`)),{image:U(s$2.siteUrl,`/seo/theory/${e.slug}.jpg`),title:r.theories[e.n].title,description:m(r.theories[e.n].short)})},loadComponent:()=>import(`./chunk-vkv4rf20.js`).then(o=>o.TheoryPageComponent)}))];var f=[{path:``,pathMatch:`full`,data:{meta:m$1(l({},z(s$2,`/theories`)),{image:U(s$2.siteUrl,`/seo/theories.jpg`),title:r.ui.title,description:m(r.ui.intro)})},loadComponent:()=>import(`./chunk-BW3wjRZX.js`).then(e=>e.TheoriesComponent)}];function m(e){if(e.length<=160)return e;let o=e.slice(0,157);return`${o.slice(0,o.lastIndexOf(` `))}\u2026`}export{f as THEORIES_ROUTES,c as THEORY_ROUTES,T as a,w as c,s as i,x as l,o as n,q as o,r$1 as r,v as s,i as t};